const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.0",
  "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../lib/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum UserType {\n  user\n  admin\n  /// Full company access plus the Permissions tab. Regular admins only see\n  /// the modules a super admin has granted them.\n  super_admin\n  worker\n  /// A landlord who can list their own properties (unapproved until an admin\n  /// approves them) and see everything scoped to properties they own.\n  owner\n}\n\n/// Sidebar / toolbar sections a regular admin can be granted. Super admins\n/// ignore this list and always have every module.\nenum AdminModule {\n  dashboard\n  onboarding\n  properties\n  tenancies\n  maintenance\n  finances\n  service_charges\n  invoices\n  expenses\n  communications\n  reports\n  suppliers\n  people\n  rejections\n  qr_code\n  dynamics\n  settings\n}\n\n/// Only meaningful when userType = worker. Distinguishes staff employed by\n/// the company (in_house) from external contractors/vendors (third_party).\nenum WorkerCategory {\n  in_house\n  third_party\n}\n\nenum Priority {\n  low\n  medium\n  high\n}\n\nenum RequestStatus {\n  pending\n  en_route\n  in_progress\n  on_hold\n  completed\n}\n\nenum SupplyRequestStatus {\n  pending\n  approved\n  denied\n}\n\nenum ChargeType {\n  rent\n  electricity\n  gas\n  water\n  internet\n  maintenance\n  municipality_fee\n  deposit\n  other\n}\n\n/// What the property management company spent money on, drawn from the\n/// yearly service charge. Mirrors the category terms already used in\n/// owners' association cash-flow statements (e.g. Urbanise Strata exports).\nenum ChargeStatus {\n  open\n  paid\n  waived\n}\n\nenum PaymentStatus {\n  pending\n  approved\n  rejected\n}\n\nenum PaymentMethod {\n  cash\n  bank_transfer\n  oman_net\n  mobile_payment\n  direct_debit\n  cheque\n  other\n}\n\n/// Who actually holds the money for a rent payment or expense — recording\n/// a payment does not necessarily mean the management company received\n/// it; the owner may have collected it directly. See Payment.collectedBy\n/// and Expense.paidBy.\nenum PaymentCollector {\n  management\n  owner\n}\n\nenum TenancyPurpose {\n  residential\n  commercial\n}\n\nenum FinancialDocumentKind {\n  bill\n  receipt\n}\n\nenum EntityDocumentCategory {\n  tenancy_agreement\n  municipality_registration\n  move_in_report\n  title_deed\n  ownership_certificate\n  /// The contract/agreement between the property manager and a unit's\n  /// owner — established when the owner's unit is set up, distinct from\n  /// `ownership_certificate` (a government-issued proof of ownership).\n  ownership_contract\n  cadastral_plan\n  building_permit\n  completion_certificate\n  noc\n  property_insurance\n  civil_id\n  passport\n  resident_card\n  visa\n  employment_letter\n  driving_license\n  vehicle_registration\n  car_insurance\n  /// The tenant's own agreement with the property manager for a parking\n  /// slot — distinct from `vehicle_registration` (a government Mulkiya),\n  /// this is the internal document assigning the slot and registering the\n  /// tenant's car against their unit.\n  parking_agreement\n  other\n}\n\n/// A configurable kind of property (apartment building, villa, office, ...).\n/// Admins can add their own instead of being limited to a fixed set, which is\n/// why the floor behaviour and unit wording live here as data, not code.\nmodel PropertyType {\n  id                   String   @id @default(uuid()) @db.Uuid\n  /// Stable machine key, e.g. \"apartment\". Never shown to users.\n  name                 String   @unique\n  /// Shown when picking a property type, e.g. \"Apartment building\".\n  label                String\n  /// Singular noun for one unit of this type, e.g. \"Apartment\", \"Villa\", \"Office\".\n  unitNounSingular     String   @map(\"unit_noun_singular\")\n  /// Plural noun, e.g. \"Apartments\", \"Villas\", \"Offices\".\n  unitNounPlural       String   @map(\"unit_noun_plural\")\n  /// Short prefix shown before a unit's label, e.g. \"Apt\" → \"Apt 101\". Null\n  /// means the unit label is shown on its own, with no prefix — the villa\n  /// convention (\"Villa 2\", not \"Villa Villa 2\").\n  unitPrefix           String?  @map(\"unit_prefix\")\n  /// Whether units of this type are organized by floor. Controls the floor\n  /// field, the \"generate by floor\" wizard and the floor grouping in the UI.\n  hasFloors            Boolean  @default(true) @map(\"has_floors\")\n  /// Whether units of this type track a bedroom count. Off for commercial\n  /// types like offices or shops, where \"bedrooms\" doesn't apply.\n  hasBedrooms          Boolean  @default(true) @map(\"has_bedrooms\")\n  /// Choices shown in \"Where is the problem?\" when a tenant of this type\n  /// reports a maintenance issue, e.g. [\"Kitchen\", \"Bathroom\", ...] for an\n  /// apartment or [\"Sales floor\", \"Storeroom\", ...] for a shop. Always ends\n  /// with a fallback \"Other\" entry.\n  locationOptions      String[] @default([\"Main area\", \"Storeroom\", \"Entrance\", \"Whole space\", \"Other\"]) @map(\"location_options\")\n  /// An owners' association type — the owner owns the whole property and\n  /// the company only manages it on their behalf. Units never bill rent,\n  /// never take maintenance requests, but the property's common areas are\n  /// always on (an OA's whole point is its shared spaces). Setting this\n  /// forces showRentBills/showMaintenance off and hasCommonAreas on,\n  /// replacing the old hardcoded name === \"building\" check — see\n  /// lib/property-types.ts. Mutually exclusive with isBuildingManagement.\n  isOwnerAssociation   Boolean  @default(false) @map(\"is_owner_association\")\n  /// A building-management type — the company doesn't own the property,\n  /// only manages several units within it on the landlord's behalf. Units\n  /// bill rent and take maintenance requests same as any rental, but the\n  /// property has no common areas of its own to manage (that's the actual\n  /// owner's concern, not the units the company manages). Setting this\n  /// forces showRentBills/showMaintenance on and hasCommonAreas off —\n  /// the mirror image of isOwnerAssociation. Replaces the old hardcoded\n  /// name === \"building_management\" check — see lib/property-types.ts.\n  isBuildingManagement Boolean  @default(false) @map(\"is_building_management\")\n  /// Whether units of this type can be billed rent & bills at all — the\n  /// per-unit \"Charge rent & bills\" toggle only appears when this is on.\n  showRentBills        Boolean  @default(true) @map(\"show_rent_bills\")\n  /// Whether units of this type can take maintenance requests at all — the\n  /// per-unit \"Accept maintenance requests\" toggle only appears when this\n  /// is on.\n  showMaintenance      Boolean  @default(true) @map(\"show_maintenance\")\n  /// Whether properties of this type have shared common areas (lobby,\n  /// parking, garden, ...) a tenant or admin can report/log against,\n  /// separately from any one unit.\n  hasCommonAreas       Boolean  @default(true) @map(\"has_common_areas\")\n  createdAt            DateTime @default(now()) @map(\"created_at\")\n  updatedAt            DateTime @updatedAt @map(\"updated_at\")\n\n  properties Property[]\n\n  @@map(\"property_types\")\n}\n\n/// A building or managed property in Oman.\nmodel Property {\n  id                            String    @id @default(uuid()) @db.Uuid\n  name                          String\n  propertyTypeId                String    @map(\"property_type_id\") @db.Uuid\n  address                       String\n  governorate                   String?\n  wilayat                       String?\n  area                          String?\n  wayNumber                     String?   @map(\"way_number\")\n  /// The building's own name/number as Rawazen's source data has it —\n  /// kept distinct from buildingNumber (the official municipal building\n  /// number) rather than merged into one field, since the two source\n  /// fields aren't always the same value.\n  buildingName                  String?   @map(\"building_name\")\n  buildingNumber                String?   @map(\"building_number\")\n  postalCode                    String?   @map(\"postal_code\")\n  titleDeedNumber               String?   @map(\"title_deed_number\")\n  plotNumber                    String?   @map(\"plot_number\")\n  /// Retained against the property for location-based functions (map\n  /// pins, JAHEZ property identification), independent of the free-text\n  /// address fields above.\n  latitude                      Decimal?  @db.Decimal(10, 7)\n  longitude                     Decimal?  @db.Decimal(10, 7)\n  /// A map link, plus code, or other location reference that isn't a raw\n  /// coordinate pair — e.g. a pasted Google Maps URL.\n  locationMapPosition           String?   @map(\"location_map_position\")\n  notes                         String?\n  /// Owners' association letterhead + bank details, printed on every\n  /// service charge invoice generated for this property's units — see\n  /// lib/pdf/service-charge-invoice.tsx.\n  associationRegistrationNumber String?   @map(\"association_registration_number\")\n  associationPhone              String?   @map(\"association_phone\")\n  bankName                      String?   @map(\"bank_name\")\n  bankSwiftCode                 String?   @map(\"bank_swift_code\")\n  bankAccountNumber             String?   @map(\"bank_account_number\")\n  paymentReference              String?   @map(\"payment_reference\")\n  chequePayableTo               String?   @map(\"cheque_payable_to\")\n  poBox                         String?   @map(\"po_box\")\n  /// Live/visible to admin, tenant and worker screens once true. Properties\n  /// an admin creates are approved immediately; properties an owner creates\n  /// start unapproved and stay hidden everywhere until an admin approves\n  /// them. Defaults to true so every pre-existing row stays live.\n  approved                      Boolean   @default(true)\n  /// When the owner submitted this property for admin review, after setting\n  /// up its units. Null means it's still a draft — the owner is adding\n  /// units and hasn't asked for approval yet, so it does NOT show up in the\n  /// admin's pending-review queue even though approved is false. Only\n  /// meaningful while approved is false; irrelevant once approved.\n  submittedAt                   DateTime? @map(\"submitted_at\")\n  /// Set when an admin rejects a submitted property (rejectPropertyAction\n  /// resets submittedAt to null so it drops out of the review queue, and\n  /// stamps these two so the owner sees why on their own property page).\n  /// Cleared again the moment the owner resubmits or an admin approves.\n  rejectedAt                    DateTime? @map(\"rejected_at\")\n  rejectionReason               String?   @map(\"rejection_reason\")\n  createdAt                     DateTime  @default(now()) @map(\"created_at\")\n  updatedAt                     DateTime  @updatedAt @map(\"updated_at\")\n\n  propertyType       PropertyType              @relation(fields: [propertyTypeId], references: [id], onDelete: Restrict)\n  units              Unit[]\n  documents          EntityDocument[]\n  commonAreaRequests MaintenanceRequest[]\n  expenses           Expense[]\n  supplierLinks      SupplierProperty[]\n  budgets            AnnualBudget[]\n  serviceContracts   BuildingServiceContract[]\n  servicesInvoices   ServicesInvoice[]\n\n  @@index([propertyTypeId])\n  @@map(\"properties\")\n}\n\n/// An apartment inside a building.\nmodel Unit {\n  id                          String    @id @default(uuid()) @db.Uuid\n  propertyId                  String    @map(\"property_id\") @db.Uuid\n  label                       String\n  floor                       Int?\n  bedrooms                    Int?\n  /// The landlord this unit belongs to. Null means no owner is assigned yet\n  /// (all units created before the owner role existed, and any an admin\n  /// hasn't assigned). Set automatically to themselves when an owner adds\n  /// the unit; only an admin can assign or reassign it. A property's\n  /// \"owner(s)\" are the distinct set of its units' owners — a property can\n  /// have several, and one owner can own units across several properties.\n  ownerId                     String?   @map(\"owner_id\") @db.Uuid\n  /// The tenant living here. Null means the apartment is empty.\n  tenantId                    String?   @unique @map(\"tenant_id\") @db.Uuid\n  /// Whether this unit is billed at all — some units (e.g. an owners\n  /// association's common-area units) are never charged rent or bills\n  /// through the system. When false, the unit and its tenant are fully\n  /// hidden from Rent & Bills: no charge can be created for it, and none of\n  /// its existing charges are shown there.\n  rentBillsEnabled            Boolean   @default(true) @map(\"rent_bills_enabled\")\n  /// Whether this unit's tenant can file maintenance requests, and whether\n  /// its recurring service-charge reminders (below) are sent at all. When\n  /// false, the report-issue flow refuses new requests for this unit and it\n  /// is hidden from the maintenance dashboard (common-area requests, which\n  /// have no unit, are unaffected).\n  maintenanceEnabled          Boolean   @default(true) @map(\"maintenance_enabled\")\n  /// Recurring maintenance budget the owner collects from/for this unit\n  /// (e.g. 400 OMR every 3 months). All three are null until someone sets\n  /// them; nulls mean \"no service charge tracked\" and the reminder job skips\n  /// the unit entirely.\n  serviceChargeAmount         Decimal?  @map(\"service_charge_amount\") @db.Decimal(14, 3)\n  serviceChargeCycleMonths    Int?      @map(\"service_charge_cycle_months\")\n  serviceChargeDueDate        DateTime? @map(\"service_charge_due_date\") @db.Date\n  /// Which reminder was last sent for the CURRENT due date, so the daily job\n  /// never sends the same stage twice (\"upcoming\" | \"due\" | \"overdue\").\n  serviceChargeLastStage      String?   @map(\"service_charge_last_stage\")\n  /// When an admin last marked the service charge as received — shown as a\n  /// confirmation tick on the unit. Cleared implicitly by simply being stale\n  /// once a new due date has since passed.\n  serviceChargeLastReceivedAt DateTime? @map(\"service_charge_last_received_at\")\n  /// When a service-charge reminder was last sent for this unit — set by\n  /// both the daily cron (lib/service-charge-reminders.ts) and the manual\n  /// \"Notify Owner\" action, so the Collection Position dashboard's \"Last\n  /// Reminder\" column has one source of truth regardless of which path\n  /// sent it.\n  serviceChargeLastReminderAt DateTime? @map(\"service_charge_last_reminder_at\")\n  /// Ownership-share weight an owners' association uses to split common\n  /// costs — printed on the service charge invoice, display-only for now\n  /// (not used in any calculation).\n  entitlements                Int?\n  /// Running service-charge ledger: positive = owed by the owner, negative\n  /// = credit owed to the owner. Updated by generateServiceChargeInvoiceAction\n  /// (adds the period's charge) and recordServiceChargePaymentAction\n  /// (subtracts a payment/credit) — see app/service-charge-invoice-actions.ts.\n  serviceChargeBalance        Decimal   @default(0) @map(\"service_charge_balance\") @db.Decimal(14, 3)\n  createdAt                   DateTime  @default(now()) @map(\"created_at\")\n  updatedAt                   DateTime  @updatedAt @map(\"updated_at\")\n\n  property              Property                       @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  owner                 User?                          @relation(\"UnitOwner\", fields: [ownerId], references: [id], onDelete: SetNull)\n  tenant                User?                          @relation(\"UnitTenant\", fields: [tenantId], references: [id], onDelete: SetNull)\n  requests              MaintenanceRequest[]\n  tenancies             Tenancy[]\n  charges               Charge[]\n  permissionChanges     UnitPermissionChange[]\n  documents             EntityDocument[]\n  expenseLinks          ExpenseUnit[]\n  serviceChargeInvoices ServiceChargeInvoice[]\n  serviceChargePayments ServiceChargePayment[]\n  installmentPlans      ServiceChargeInstallmentPlan[]\n  fundBalances          UnitFundBalance[]\n  ownershipTransfers    OwnershipTransfer[]\n  servicesInvoices      ServicesInvoice[]\n\n  @@unique([propertyId, label])\n  @@index([propertyId])\n  @@index([ownerId])\n  @@map(\"units\")\n}\n\n/// Append-only log of when a unit's rent-bills/maintenance toggles changed.\n/// Not surfaced anywhere yet — it exists purely so a future report can\n/// reconstruct, after the fact, which periods a unit was billed through the\n/// system vs. handled outside it. That's the only scenario (e.g. a\n/// building-management unit toggled off for two months, then back on) where\n/// \"what is it set to right now\" isn't enough: without this log, once a\n/// cycle passes there is no way to recover what it was set to during it.\nmodel UnitPermissionChange {\n  id          String   @id @default(uuid()) @db.Uuid\n  unitId      String   @map(\"unit_id\") @db.Uuid\n  /// Which toggle changed: \"rentBillsEnabled\" | \"maintenanceEnabled\".\n  field       String\n  fromValue   Boolean  @map(\"from_value\")\n  toValue     Boolean  @map(\"to_value\")\n  changedById String?  @map(\"changed_by\") @db.Uuid\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n\n  unit      Unit  @relation(fields: [unitId], references: [id], onDelete: Cascade)\n  changedBy User? @relation(fields: [changedById], references: [id], onDelete: SetNull)\n\n  @@index([unitId, createdAt])\n  @@map(\"unit_permission_changes\")\n}\n\n/// A recorded handover of one unit from its current owner to a new one —\n/// the professional alternative to just overwriting Unit.ownerId, which\n/// left no record of who owned a unit before or when the change happened.\n/// The old ownership ends and the new one starts on the same transferDate,\n/// same as a real sale/handover would.\nmodel OwnershipTransfer {\n  id                  String   @id @default(uuid()) @db.Uuid\n  unitId              String   @map(\"unit_id\") @db.Uuid\n  /// Null when the unit had no owner before this (a first assignment\n  /// recorded through the same flow, not just a bare transfer).\n  fromOwnerId         String?  @map(\"from_owner_id\") @db.Uuid\n  toOwnerId           String   @map(\"to_owner_id\") @db.Uuid\n  transferDate        DateTime @map(\"transfer_date\") @db.Date\n  /// Whether the unit's existing service charge amount/cycle/due date carry\n  /// over to the new owner unchanged, or were cleared for the admin to set\n  /// up fresh for them.\n  keptServiceCharge   Boolean  @default(true) @map(\"kept_service_charge\")\n  /// Whether an active installment plan stayed in place for the new owner\n  /// (true) or was cancelled so they can set up a different schedule.\n  keptInstallmentPlan Boolean  @default(true) @map(\"kept_installment_plan\")\n  notes               String?\n  createdById         String?  @map(\"created_by\") @db.Uuid\n  createdAt           DateTime @default(now()) @map(\"created_at\")\n\n  unit      Unit  @relation(fields: [unitId], references: [id], onDelete: Cascade)\n  fromOwner User? @relation(\"OwnershipTransferFromOwner\", fields: [fromOwnerId], references: [id], onDelete: SetNull)\n  toOwner   User  @relation(\"OwnershipTransferToOwner\", fields: [toOwnerId], references: [id], onDelete: Restrict)\n  createdBy User? @relation(\"OwnershipTransferCreator\", fields: [createdById], references: [id], onDelete: SetNull)\n\n  @@index([unitId, createdAt])\n  @@map(\"ownership_transfers\")\n}\n\n/// Account and profile in one row. `userType` drives every authorization check.\n/// `id` is not generated here — it is the id of the matching row in Supabase\n/// Auth's `auth.users`, which credentials and password hashing live in; see\n/// the `_supabase_auth` migration for the foreign key that ties the two together.\nmodel User {\n  id                          String          @id @db.Uuid\n  /// Unique per role, not globally: a tenant and a worker (etc.) can share an\n  /// email, but two tenants (or two workers) can't. See @@unique below.\n  email                       String\n  userType                    UserType        @default(user) @map(\"user_type\")\n  /// Only set when userType = worker: whether this worker is in-house staff\n  /// or a 3rd-party contractor/vendor.\n  workerCategory              WorkerCategory? @map(\"worker_category\")\n  /// Only meaningful for 3rd-party workers: the vendor/company name shown\n  /// alongside their contact info wherever they're listed.\n  companyName                 String?         @map(\"company_name\")\n  firstName                   String?         @map(\"first_name\")\n  lastName                    String?         @map(\"last_name\")\n  phone                       String?         @unique\n  civilId                     String?         @unique @map(\"civil_id\")\n  nationality                 String?\n  employer                    String?\n  /// Owner's own postal address — the \"bill to\" block on a service charge\n  /// invoice, distinct from any property's address.\n  mailingAddress              String?         @map(\"mailing_address\")\n  emergencyContactName        String?         @map(\"emergency_contact_name\")\n  emergencyContactPhone       String?         @map(\"emergency_contact_phone\")\n  /// The following are only meaningful for in-house workers — the paperwork\n  /// required to legally employ someone in the Gulf. Third-party\n  /// contractors' documents are their own employer's responsibility, not\n  /// tracked here.\n  passportNumber              String?         @map(\"passport_number\")\n  passportIssuance            DateTime?       @map(\"passport_issuance\")\n  passportExpiry              DateTime?       @map(\"passport_expiry\")\n  /// Work visa / residency permit.\n  visaNumber                  String?         @map(\"visa_number\")\n  visaIssuance                DateTime?       @map(\"visa_issuance\")\n  visaExpiry                  DateTime?       @map(\"visa_expiry\")\n  /// Issuance/expiry of the Civil ID / Resident Card already captured in\n  /// `civilId`.\n  civilIdIssuance             DateTime?       @map(\"civil_id_issuance\")\n  civilIdExpiry               DateTime?       @map(\"civil_id_expiry\")\n  drivingLicenseNumber        String?         @map(\"driving_license_number\")\n  drivingLicenseIssuance      DateTime?       @map(\"driving_license_issuance\")\n  drivingLicenseExpiry        DateTime?       @map(\"driving_license_expiry\")\n  /// Only meaningful for in-house workers: \"individual\" (default) or\n  /// \"family\" — a family employee's dependents (spouse/father/mother) get\n  /// their own Bataka records tracked below via familyMembers.\n  employeeType                String          @default(\"individual\") @map(\"employee_type\")\n  /// Whether this worker has/drives a vehicle for work — gates whether the\n  /// vehicle documents below are asked for at all.\n  hasVehicle                  Boolean         @default(false) @map(\"has_vehicle\")\n  /// Mulkiya — vehicle registration.\n  vehicleRegistrationNumber   String?         @map(\"vehicle_registration_number\")\n  vehicleRegistrationIssuance DateTime?       @map(\"vehicle_registration_issuance\")\n  vehicleRegistrationExpiry   DateTime?       @map(\"vehicle_registration_expiry\")\n  carInsuranceNumber          String?         @map(\"car_insurance_number\")\n  carInsuranceIssuance        DateTime?       @map(\"car_insurance_issuance\")\n  carInsuranceExpiry          DateTime?       @map(\"car_insurance_expiry\")\n  /// What was last sent for each HR document's expiry cycle — e.g.\n  /// {\"passport\": \"upcoming\", \"visa\": \"overdue:3\"} — so the daily reminder\n  /// job (lib/hr-reminders.ts) doesn't repeat the same nudge. Mirrors\n  /// Property.serviceChargeLastStage's pattern, generalized to several\n  /// documents per person instead of one charge per property.\n  hrReminderStages            Json?           @map(\"hr_reminder_stages\")\n  createdAt                   DateTime        @default(now()) @map(\"created_at\")\n  updatedAt                   DateTime        @updatedAt @map(\"updated_at\")\n\n  /// Set only for tenants: the apartment they live in.\n  unit                            Unit?                          @relation(\"UnitTenant\")\n  requests                        MaintenanceRequest[]           @relation(\"RequestOwner\")\n  assignedRequests                MaintenanceRequest[]           @relation(\"AssignedWorker\")\n  createdRequests                 MaintenanceRequest[]           @relation(\"RequestCreatedBy\")\n  attachments                     MaintenanceAttachment[]\n  taskLogs                        TaskLog[]\n  notifications                   Notification[]\n  tenancies                       Tenancy[]                      @relation(\"TenancyTenant\")\n  charges                         Charge[]                       @relation(\"ChargeTenant\")\n  createdCharges                  Charge[]                       @relation(\"ChargeCreator\")\n  submittedPayments               Payment[]                      @relation(\"PaymentSubmitter\")\n  reviewedPayments                Payment[]                      @relation(\"PaymentReviewer\")\n  financialUploads                FinancialAttachment[]          @relation(\"FinancialUploader\")\n  documents                       EntityDocument[]               @relation(\"UserDocuments\")\n  documentUploads                 EntityDocument[]               @relation(\"EntityDocumentUploader\")\n  supplyRequestsMade              SupplyRequest[]                @relation(\"SupplyRequestedBy\")\n  supplyRequestsDecided           SupplyRequest[]                @relation(\"SupplyDecidedBy\")\n  expensesCreated                 Expense[]                      @relation(\"ExpenseCreator\")\n  serviceChargeInvoicesCreated    ServiceChargeInvoice[]         @relation(\"ServiceChargeInvoiceCreator\")\n  serviceChargeInvoicesBilled     ServiceChargeInvoice[]         @relation(\"ServiceChargeInvoiceBilledOwner\")\n  serviceChargePaymentsCreated    ServiceChargePayment[]         @relation(\"ServiceChargePaymentCreator\")\n  serviceChargePaymentsBilled     ServiceChargePayment[]         @relation(\"ServiceChargePaymentBilledOwner\")\n  serviceChargePaymentsCorrected  ServiceChargePayment[]         @relation(\"ServiceChargePaymentCorrector\")\n  serviceChargePlansCreated       ServiceChargeInstallmentPlan[] @relation(\"ServiceChargePlanCreator\")\n  suppliersCreated                Supplier[]                     @relation(\"SupplierCreator\")\n  buildingServiceContractsCreated BuildingServiceContract[]      @relation(\"BuildingServiceContractCreator\")\n  annualBudgetsCreated            AnnualBudget[]                 @relation(\"AnnualBudgetCreator\")\n  /// Set only for owners: the units they were assigned or created.\n  ownedUnits                      Unit[]                         @relation(\"UnitOwner\")\n  whatsappSessions                WhatsappSession[]\n  /// Rejections this admin issued (property, payment, or supply request).\n  rejectionLogs                   RejectionLog[]\n  /// Toggle changes this admin made on a unit's rent-bills/maintenance\n  /// permissions — see UnitPermissionChange.\n  unitPermissionChanges           UnitPermissionChange[]\n  ownershipTransfersFrom          OwnershipTransfer[]            @relation(\"OwnershipTransferFromOwner\")\n  ownershipTransfersTo            OwnershipTransfer[]            @relation(\"OwnershipTransferToOwner\")\n  ownershipTransfersCreated       OwnershipTransfer[]            @relation(\"OwnershipTransferCreator\")\n  /// Only populated when employeeType = \"family\" — the worker's tracked\n  /// dependents (see WorkerFamilyMember).\n  familyMembers                   WorkerFamilyMember[]\n  servicesInvoicesCreated         ServicesInvoice[]              @relation(\"ServicesInvoiceCreator\")\n  communicationsLogged            CommunicationLog[]             @relation(\"CommunicationLogger\")\n  communicationsAsParty           CommunicationLog[]             @relation(\"CommunicationParty\")\n  adminModuleGrants               AdminModuleGrant[]\n\n  @@unique([email, userType])\n  @@map(\"users\")\n}\n\n/// One granted sidebar module for a regular admin. Absence of a row means\n/// that module is hidden. Super admins do not need rows here.\nmodel AdminModuleGrant {\n  id        String      @id @default(uuid()) @db.Uuid\n  userId    String      @map(\"user_id\") @db.Uuid\n  module    AdminModule\n  createdAt DateTime    @default(now()) @map(\"created_at\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, module])\n  @@index([userId])\n  @@map(\"admin_module_grants\")\n}\n\nenum FamilyRelationship {\n  spouse\n  father\n  mother\n  child\n}\n\n/// A dependent (spouse/father/mother) tracked for an in-house worker whose\n/// employeeType is \"family\" — mirrors the worker's own Bataka tracking, one\n/// record per dependent. Limits (up to 4 spouses, 1 father, 1 mother) are\n/// enforced in the server action, not here.\nmodel WorkerFamilyMember {\n  id               String             @id @default(uuid()) @db.Uuid\n  workerId         String             @map(\"worker_id\") @db.Uuid\n  name             String\n  relationship     FamilyRelationship\n  civilIdIssuance  DateTime?          @map(\"civil_id_issuance\")\n  civilIdExpiry    DateTime?          @map(\"civil_id_expiry\")\n  documentFileName String?            @map(\"document_file_name\")\n  documentFilePath String?            @map(\"document_file_path\")\n  documentFileType String?            @map(\"document_file_type\")\n  documentFileSize Int?               @map(\"document_file_size\")\n  createdAt        DateTime           @default(now()) @map(\"created_at\")\n  updatedAt        DateTime           @updatedAt @map(\"updated_at\")\n\n  worker User @relation(fields: [workerId], references: [id], onDelete: Cascade)\n\n  @@index([workerId])\n  @@map(\"worker_family_members\")\n}\n\n/// A historical occupancy record. Unit.tenantId remains the fast pointer to the\n/// current occupant; this model preserves the commercial terms and move history.\nmodel Tenancy {\n  id                         String         @id @default(uuid()) @db.Uuid\n  unitId                     String         @map(\"unit_id\") @db.Uuid\n  tenantId                   String         @map(\"tenant_id\") @db.Uuid\n  startDate                  DateTime       @map(\"start_date\") @db.Date\n  endDate                    DateTime?      @map(\"end_date\") @db.Date\n  leaseEndDate               DateTime?      @map(\"lease_end_date\") @db.Date\n  /// The signed agreement's own start date, when it differs from the\n  /// tenant's actual move-in (startDate) — e.g. a contract dated a few\n  /// days before check-in. Defaults to startDate when not set separately.\n  agreementStartDate         DateTime?      @map(\"agreement_start_date\") @db.Date\n  monthlyRent                Decimal        @default(0) @map(\"monthly_rent\") @db.Decimal(14, 3)\n  rentDueDay                 Int            @default(5) @map(\"rent_due_day\")\n  securityDeposit            Decimal        @default(0) @map(\"security_deposit\") @db.Decimal(14, 3)\n  purpose                    TenancyPurpose @default(residential)\n  agreementRef               String?        @map(\"agreement_ref\")\n  /// Who actually pays the rent — usually the tenant themselves, but can\n  /// be a sponsoring employer or third party. Free text, not a User link,\n  /// since it's often not a system account.\n  paidBy                     String?        @map(\"paid_by\")\n  municipalityContractNumber String?        @map(\"municipality_contract_number\")\n  contractRegisteredAt       DateTime?      @map(\"contract_registered_at\") @db.Date\n  electricityAccountNumber   String?        @map(\"electricity_account_number\")\n  waterAccountNumber         String?        @map(\"water_account_number\")\n  /// A parking slot is its own small agreement between the tenant and the\n  /// property manager — the tenant registers a car against it, so the\n  /// vehicle is tied to their unit the same way a Mulkiya ties a car to its\n  /// owner. Free text, not a separate model: one slot/one vehicle per\n  /// tenancy is the common case, and the signed agreement itself is stored\n  /// as an EntityDocument (see EntityDocumentCategory.parking_agreement).\n  parkingSlotNumber          String?        @map(\"parking_slot_number\")\n  vehiclePlateNumber         String?        @map(\"vehicle_plate_number\")\n  vehicleDetails             String?        @map(\"vehicle_details\")\n  notes                      String?\n  createdAt                  DateTime       @default(now()) @map(\"created_at\")\n  updatedAt                  DateTime       @updatedAt @map(\"updated_at\")\n\n  unit             Unit              @relation(fields: [unitId], references: [id], onDelete: Cascade)\n  tenant           User              @relation(\"TenancyTenant\", fields: [tenantId], references: [id], onDelete: Cascade)\n  charges          Charge[]\n  documents        EntityDocument[]\n  servicesInvoices ServicesInvoice[]\n\n  @@index([unitId, endDate])\n  @@index([tenantId, endDate])\n  @@map(\"tenancies\")\n}\n\n/// Private supporting documents belonging to exactly one property, tenancy or person.\nmodel EntityDocument {\n  id           String                 @id @default(uuid()) @db.Uuid\n  propertyId   String?                @map(\"property_id\") @db.Uuid\n  unitId       String?                @map(\"unit_id\") @db.Uuid\n  tenancyId    String?                @map(\"tenancy_id\") @db.Uuid\n  userId       String?                @map(\"user_id\") @db.Uuid\n  category     EntityDocumentCategory\n  label        String?\n  fileName     String                 @map(\"file_name\")\n  filePath     String                 @map(\"file_path\")\n  fileType     String                 @map(\"file_type\")\n  fileSize     Int                    @map(\"file_size\")\n  /// When this document stops being valid (a contract's term, an ID's\n  /// validity, an insurance policy's coverage, ...). Null means it doesn't\n  /// expire. Feeds the same 90/60/30/15/7-day reminder ladder as tenant\n  /// and building agreements — see lib/agreement-expiry.ts.\n  expiresAt    DateTime?              @map(\"expires_at\") @db.Date\n  uploadedById String?                @map(\"uploaded_by\") @db.Uuid\n  createdAt    DateTime               @default(now()) @map(\"created_at\")\n\n  property   Property? @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  unit       Unit?     @relation(fields: [unitId], references: [id], onDelete: Cascade)\n  tenancy    Tenancy?  @relation(fields: [tenancyId], references: [id], onDelete: Cascade)\n  user       User?     @relation(\"UserDocuments\", fields: [userId], references: [id], onDelete: Cascade)\n  uploadedBy User?     @relation(\"EntityDocumentUploader\", fields: [uploadedById], references: [id], onDelete: SetNull)\n\n  @@index([propertyId, createdAt])\n  @@index([unitId, createdAt])\n  @@index([tenancyId, createdAt])\n  @@index([userId, createdAt])\n  @@map(\"entity_documents\")\n}\n\n/// One amount due from a tenant. Approved payments can be partial; the charge is\n/// closed only once their total reaches the amount due.\nmodel Charge {\n  id          String       @id @default(uuid()) @db.Uuid\n  tenancyId   String       @map(\"tenancy_id\") @db.Uuid\n  unitId      String       @map(\"unit_id\") @db.Uuid\n  tenantId    String       @map(\"tenant_id\") @db.Uuid\n  type        ChargeType\n  title       String\n  amount      Decimal      @db.Decimal(14, 3)\n  dueDate     DateTime     @map(\"due_date\") @db.Date\n  periodStart DateTime?    @map(\"period_start\") @db.Date\n  status      ChargeStatus @default(open)\n  notes       String?\n  /// Set only for generated rent, making generation safely repeatable.\n  rentKey     String?      @unique @map(\"rent_key\")\n  createdById String?      @map(\"created_by\") @db.Uuid\n  createdAt   DateTime     @default(now()) @map(\"created_at\")\n  updatedAt   DateTime     @updatedAt @map(\"updated_at\")\n\n  tenancy     Tenancy               @relation(fields: [tenancyId], references: [id], onDelete: Cascade)\n  unit        Unit                  @relation(fields: [unitId], references: [id], onDelete: Cascade)\n  tenant      User                  @relation(\"ChargeTenant\", fields: [tenantId], references: [id], onDelete: Cascade)\n  createdBy   User?                 @relation(\"ChargeCreator\", fields: [createdById], references: [id], onDelete: SetNull)\n  payments    Payment[]\n  attachments FinancialAttachment[]\n\n  @@index([tenantId, status, dueDate])\n  @@index([unitId, dueDate])\n  @@index([tenancyId, periodStart])\n  @@index([type])\n  @@map(\"charges\")\n}\n\nmodel Payment {\n  id                String           @id @default(uuid()) @db.Uuid\n  chargeId          String           @map(\"charge_id\") @db.Uuid\n  amount            Decimal          @db.Decimal(14, 3)\n  paidAt            DateTime         @map(\"paid_at\") @db.Date\n  method            PaymentMethod\n  reference         String?\n  notes             String?\n  status            PaymentStatus    @default(pending)\n  /// Who actually holds this money — recording a payment doesn't mean the\n  /// management company received it; the owner may have collected it\n  /// directly. Distinct from submittedById, which is just who filed the\n  /// record in the system.\n  collectedBy       PaymentCollector @default(management) @map(\"collected_by\")\n  /// The person who physically received the cash/cheque, if worth naming\n  /// separately from the system user who submitted the record.\n  receivedByName    String?          @map(\"received_by_name\")\n  /// Free-form bank transfer reference, same idiom as\n  /// ServiceChargePayment.transactionNumber.\n  transactionNumber String?          @map(\"transaction_number\")\n  chequeNumber      String?          @map(\"cheque_number\")\n  chequeDate        DateTime?        @map(\"cheque_date\") @db.Date\n  bank              String?\n  /// Simple string (\"pending\" | \"cleared\" | \"bounced\"), same idiom as\n  /// ServiceChargePayment.clearanceStatus.\n  clearanceStatus   String?          @map(\"clearance_status\")\n  submittedById     String           @map(\"submitted_by\") @db.Uuid\n  reviewedById      String?          @map(\"reviewed_by\") @db.Uuid\n  reviewedAt        DateTime?        @map(\"reviewed_at\")\n  reviewNotes       String?          @map(\"review_notes\")\n  createdAt         DateTime         @default(now()) @map(\"created_at\")\n  updatedAt         DateTime         @updatedAt @map(\"updated_at\")\n\n  charge      Charge                @relation(fields: [chargeId], references: [id], onDelete: Cascade)\n  submittedBy User                  @relation(\"PaymentSubmitter\", fields: [submittedById], references: [id], onDelete: Restrict)\n  reviewedBy  User?                 @relation(\"PaymentReviewer\", fields: [reviewedById], references: [id], onDelete: SetNull)\n  attachments FinancialAttachment[]\n\n  @@index([chargeId, status])\n  @@index([status, createdAt])\n  @@index([method, chequeDate])\n  @@map(\"payments\")\n}\n\nmodel FinancialAttachment {\n  id           String                @id @default(uuid()) @db.Uuid\n  chargeId     String?               @map(\"charge_id\") @db.Uuid\n  paymentId    String?               @map(\"payment_id\") @db.Uuid\n  kind         FinancialDocumentKind\n  fileName     String                @map(\"file_name\")\n  filePath     String                @map(\"file_path\")\n  fileType     String                @map(\"file_type\")\n  fileSize     Int                   @map(\"file_size\")\n  uploadedById String?               @map(\"uploaded_by\") @db.Uuid\n  createdAt    DateTime              @default(now()) @map(\"created_at\")\n\n  charge     Charge?  @relation(fields: [chargeId], references: [id], onDelete: Cascade)\n  payment    Payment? @relation(fields: [paymentId], references: [id], onDelete: Cascade)\n  uploadedBy User?    @relation(\"FinancialUploader\", fields: [uploadedById], references: [id], onDelete: SetNull)\n\n  @@index([chargeId])\n  @@index([paymentId])\n  @@map(\"financial_attachments\")\n}\n\n/// Money the management company spent, drawn from the service charge —\n/// logged against either a whole property (e.g. lobby cleaning) or one\n/// specific unit. Exactly one of propertyId/unitId is set, same idiom as\n/// MaintenanceRequest's unit-vs-common-area split.\nmodel Expense {\n  id                String           @id @default(uuid()) @db.Uuid\n  propertyId        String?          @map(\"property_id\") @db.Uuid\n  categoryId        String           @map(\"category_id\") @db.Uuid\n  /// One of the chosen category's ExpenseSubcategoryType labels (validated\n  /// in the server action, not a DB FK — kept as a plain string since it's\n  /// just a label copy, same idiom the old hardcoded list used).\n  subcategory       String?\n  /// The vendor this was paid to, if any — null means \"Company default\"\n  /// (no external supplier), not a database row. See Supplier above.\n  supplierId        String?          @map(\"supplier_id\") @db.Uuid\n  description       String\n  amount            Decimal          @db.Decimal(14, 3)\n  /// VAT charged on this expense, if any — kept as its own amount (not a\n  /// rate) since that's what a supplier invoice actually states.\n  vatAmount         Decimal          @default(0) @map(\"vat_amount\") @db.Decimal(14, 3)\n  /// Which OA fund this expense is paid out of — required, like\n  /// ServiceChargeInvoice.fundId, so every fund's Cash Flow Statement can\n  /// filter expenditure by it.\n  fundId            String           @map(\"fund_id\") @db.Uuid\n  /// Free-form bank transfer/cheque reference, same idiom as\n  /// ServiceChargePayment.transactionNumber.\n  paymentReference  String?          @map(\"payment_reference\")\n  /// Who actually paid this expense — same distinction as\n  /// Payment.collectedBy: did it come out of the management company's own\n  /// float, or did the owner pay the supplier directly.\n  paidBy            PaymentCollector @default(management) @map(\"paid_by\")\n  /// Only meaningful for a non-OA property (villa/apartment/office/building\n  /// management) — those never had a \"service charge\" concept before this,\n  /// so an expense against one of their units needs to say whether it's\n  /// billed to the owner as its own extra charge, or absorbed by/deducted\n  /// from the OA service charge already being collected for that unit.\n  /// Same idiom as clearanceStatus: a plain string, not an enum, since it's\n  /// two admin-picked values that would only cause migration friction as\n  /// an enum if a third ever gets added. Ignored entirely for OA units.\n  ownerChargeMethod String           @default(\"extra_charge\") @map(\"owner_charge_method\")\n  notes             String?\n  date              DateTime         @db.Date\n  /// The uploaded invoice/receipt, if any. Single file, so inline rather\n  /// than a separate attachment table — same idiom as SupplyRequest's\n  /// receiptPath/receiptFileName/receiptFileType.\n  receiptFileName   String?          @map(\"receipt_file_name\")\n  receiptFilePath   String?          @map(\"receipt_file_path\")\n  receiptFileType   String?          @map(\"receipt_file_type\")\n  receiptFileSize   Int?             @map(\"receipt_file_size\")\n  createdById       String?          @map(\"created_by\") @db.Uuid\n  createdAt         DateTime         @default(now()) @map(\"created_at\")\n  updatedAt         DateTime         @updatedAt @map(\"updated_at\")\n\n  property  Property?           @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  category  ExpenseCategoryType @relation(fields: [categoryId], references: [id], onDelete: Restrict)\n  supplier  Supplier?           @relation(fields: [supplierId], references: [id], onDelete: SetNull)\n  fund      Fund                @relation(fields: [fundId], references: [id], onDelete: Restrict)\n  createdBy User?               @relation(\"ExpenseCreator\", fields: [createdById], references: [id], onDelete: SetNull)\n  /// The unit(s) this expense is split across when it isn't property-wide —\n  /// a many-to-many join (not a single unitId) so one shared cost logged\n  /// against several units stays ONE row with the amount as entered,\n  /// instead of being duplicated per unit. Exactly one of propertyId /\n  /// units is set — validated in createExpenseAction, since a join table\n  /// can't be covered by a simple CHECK constraint.\n  units     ExpenseUnit[]\n\n  @@index([propertyId, date])\n  @@index([categoryId])\n  @@index([supplierId])\n  @@index([fundId])\n  @@map(\"expenses\")\n}\n\nmodel ExpenseUnit {\n  expenseId String @map(\"expense_id\") @db.Uuid\n  unitId    String @map(\"unit_id\") @db.Uuid\n\n  expense Expense @relation(fields: [expenseId], references: [id], onDelete: Cascade)\n  unit    Unit    @relation(fields: [unitId], references: [id], onDelete: Cascade)\n\n  @@id([expenseId, unitId])\n  @@index([unitId])\n  @@map(\"expense_units\")\n}\n\n/// Admin-manageable OA accounting fund (General Administrative Fund, Admin\n/// Fund, Sinking Fund, ...) — same idiom as PropertyType/ExpenseCategoryType.\n/// Every invoice line and payment can tag one, and Unit.serviceChargeBalance\n/// (the maintained grand total) is backed by a real per-fund balance in\n/// UnitFundBalance below, instead of treating every amount as one number.\nmodel Fund {\n  id        String   @id @default(uuid()) @db.Uuid\n  /// Stable slug, e.g. \"sinking\".\n  name      String   @unique\n  label     String\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  invoiceLines          ServiceChargeInvoiceLine[]\n  payments              ServiceChargePayment[]\n  balances              UnitFundBalance[]\n  expenseLines          BudgetExpenseLine[]\n  serviceChargeInvoices ServiceChargeInvoice[]\n  expenses              Expense[]\n\n  @@map(\"funds\")\n}\n\n/// A unit's running balance within one fund — positive = owed by the\n/// owner, negative = credit, same sign convention as\n/// Unit.serviceChargeBalance (which is simply the sum of these rows across\n/// every fund, kept in sync in the same transaction as any write here so\n/// existing total-balance UI never has to change).\nmodel UnitFundBalance {\n  unitId  String  @map(\"unit_id\") @db.Uuid\n  fundId  String  @map(\"fund_id\") @db.Uuid\n  balance Decimal @default(0) @db.Decimal(14, 3)\n\n  unit Unit @relation(fields: [unitId], references: [id], onDelete: Cascade)\n  fund Fund @relation(fields: [fundId], references: [id], onDelete: Restrict)\n\n  @@id([unitId, fundId])\n  @@index([fundId])\n  @@map(\"unit_fund_balances\")\n}\n\n/// One generated owner service-charge invoice for a unit — see\n/// app/service-charge-invoice-actions.ts for the balance math and\n/// lib/pdf/service-charge-invoice.tsx for the printed layout. Bills exactly\n/// one fund (see ServiceChargeInvoiceLine) — billing two funds in the same\n/// period means generating two invoices, same as two real invoice numbers.\nmodel ServiceChargeInvoice {\n  id              String    @id @default(uuid()) @db.Uuid\n  unitId          String    @map(\"unit_id\") @db.Uuid\n  fundId          String    @map(\"fund_id\") @db.Uuid\n  invoiceNumber   String    @unique @map(\"invoice_number\")\n  issueDate       DateTime  @map(\"issue_date\") @db.Date\n  dueDate         DateTime  @map(\"due_date\") @db.Date\n  /// Days of grace after dueDate before this invoice counts as overdue —\n  /// printed on the invoice, 0 means none.\n  graceDays       Int       @default(0) @map(\"grace_days\")\n  periodStart     DateTime  @map(\"period_start\") @db.Date\n  periodEnd       DateTime  @map(\"period_end\") @db.Date\n  /// This fund's UnitFundBalance as it stood before this invoice.\n  previousBalance Decimal   @map(\"previous_balance\") @db.Decimal(14, 3)\n  currentAmount   Decimal   @map(\"current_amount\") @db.Decimal(14, 3)\n  amountPayable   Decimal   @map(\"amount_payable\") @db.Decimal(14, 3)\n  /// previousBalance + currentAmount — becomes this fund's UnitFundBalance\n  /// once this invoice is created, and the next invoice's previousBalance.\n  closingBalance  Decimal   @map(\"closing_balance\") @db.Decimal(14, 3)\n  /// Owner billed when this invoice was generated — kept even if the unit\n  /// later changes hands, so the ledger and PDF stay historically accurate.\n  billedOwnerId   String?   @map(\"billed_owner_id\") @db.Uuid\n  /// service_charge (recurring OA charge) | additional (one-off against a unit)\n  kind            String    @default(\"service_charge\")\n  /// draft | issued | void — drafts do not move the ledger until issued.\n  status          String    @default(\"issued\")\n  notes           String?\n  sentAt          DateTime? @map(\"sent_at\")\n  createdById     String?   @map(\"created_by\") @db.Uuid\n  createdAt       DateTime  @default(now()) @map(\"created_at\")\n\n  unit             Unit                           @relation(fields: [unitId], references: [id], onDelete: Cascade)\n  fund             Fund                           @relation(fields: [fundId], references: [id], onDelete: Restrict)\n  billedOwner      User?                          @relation(\"ServiceChargeInvoiceBilledOwner\", fields: [billedOwnerId], references: [id], onDelete: SetNull)\n  createdBy        User?                          @relation(\"ServiceChargeInvoiceCreator\", fields: [createdById], references: [id], onDelete: SetNull)\n  lines            ServiceChargeInvoiceLine[]\n  installmentPlans ServiceChargeInstallmentPlan[]\n\n  @@index([unitId, issueDate])\n  @@map(\"service_charge_invoices\")\n}\n\n/// The Fund/Description/Unit Rate/Qty/Totals line on an invoice. v1 always\n/// creates exactly one, matching the invoice's own fundId/currentAmount —\n/// kept as its own table (not flattened onto the invoice) so a future\n/// multi-line invoice is additive, not a rewrite.\nmodel ServiceChargeInvoiceLine {\n  id          String  @id @default(uuid()) @db.Uuid\n  invoiceId   String  @map(\"invoice_id\") @db.Uuid\n  fundId      String  @map(\"fund_id\") @db.Uuid\n  description String\n  unitRate    Decimal @map(\"unit_rate\") @db.Decimal(14, 3)\n  qty         Decimal @default(1) @db.Decimal(10, 2)\n  total       Decimal @db.Decimal(14, 3)\n\n  invoice ServiceChargeInvoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n  fund    Fund                 @relation(fields: [fundId], references: [id], onDelete: Restrict)\n\n  @@map(\"service_charge_invoice_lines\")\n}\n\n/// A payment or manual credit adjustment against a unit's running service\n/// charge balance — subtracts from Unit.serviceChargeBalance (and, when\n/// fundId is set, from that fund's own UnitFundBalance too), so enough of\n/// these can push it negative (a credit) exactly like the reference\n/// invoice's \"Previous Balance: (400.00)\". fundId is nullable because\n/// installment-plan payments (app/service-charge-installment-actions.ts)\n/// and generic payments deliberately move only the total, not one fund.\nmodel ServiceChargePayment {\n  id                String         @id @default(uuid()) @db.Uuid\n  unitId            String         @map(\"unit_id\") @db.Uuid\n  fundId            String?        @map(\"fund_id\") @db.Uuid\n  amount            Decimal        @db.Decimal(14, 3)\n  paidAt            DateTime       @map(\"paid_at\") @db.Date\n  /// Free-form reference for a bank transfer/receipt, distinct from a\n  /// cheque's own number below.\n  transactionNumber String?        @map(\"transaction_number\")\n  paymentMethod     PaymentMethod? @map(\"payment_method\")\n  chequeNumber      String?        @map(\"cheque_number\")\n  chequeDate        DateTime?      @map(\"cheque_date\") @db.Date\n  bank              String?\n  /// Simple string (\"pending\" | \"cleared\" | \"bounced\") rather than a full\n  /// enum — three values an admin picks from a select, never scripted\n  /// against, so an enum would only add migration friction if it changes.\n  clearanceStatus   String?        @map(\"clearance_status\")\n  note              String?\n  /// The amount as first recorded, set the first time this payment is\n  /// corrected (and never touched again after that) — so a mistyped 3500\n  /// instead of 350 still has its true original on file even after\n  /// several corrections. Null means it has never been corrected.\n  originalAmount    Decimal?       @map(\"original_amount\") @db.Decimal(14, 3)\n  /// Why the amount was changed after the fact — required by\n  /// correctServiceChargePaymentAction, distinct from `note` (the reason\n  /// for the payment itself).\n  correctionNote    String?        @map(\"correction_note\")\n  correctedAt       DateTime?      @map(\"corrected_at\")\n  correctedById     String?        @map(\"corrected_by\") @db.Uuid\n  /// Owner of the unit when this payment was recorded.\n  billedOwnerId     String?        @map(\"billed_owner_id\") @db.Uuid\n  createdById       String?        @map(\"created_by\") @db.Uuid\n  createdAt         DateTime       @default(now()) @map(\"created_at\")\n\n  unit        Unit                      @relation(fields: [unitId], references: [id], onDelete: Cascade)\n  fund        Fund?                     @relation(fields: [fundId], references: [id], onDelete: SetNull)\n  billedOwner User?                     @relation(\"ServiceChargePaymentBilledOwner\", fields: [billedOwnerId], references: [id], onDelete: SetNull)\n  createdBy   User?                     @relation(\"ServiceChargePaymentCreator\", fields: [createdById], references: [id], onDelete: SetNull)\n  correctedBy User?                     @relation(\"ServiceChargePaymentCorrector\", fields: [correctedById], references: [id], onDelete: SetNull)\n  installment ServiceChargeInstallment?\n\n  @@index([unitId, paidAt])\n  @@map(\"service_charge_payments\")\n}\n\n/// A schedule for paying off a unit's outstanding service-charge balance\n/// over several installments instead of one lump sum. unitId-scoped like\n/// the rest of the ledger above, so it carries forward automatically if the\n/// unit changes owners mid-plan — nothing to migrate, updateUnitAction only\n/// ever touches Unit.ownerId.\nmodel ServiceChargeInstallmentPlan {\n  id               String    @id @default(uuid()) @db.Uuid\n  unitId           String    @map(\"unit_id\") @db.Uuid\n  /// The annual invoice this plan is paying off, when one exists — used to\n  /// render installment PDFs from the same billed period.\n  sourceInvoiceId  String?   @map(\"source_invoice_id\") @db.Uuid\n  /// Unit.serviceChargeBalance as it stood when the plan was created —\n  /// fixed at setup time; charges accrued afterwards aren't folded in.\n  totalAmount      Decimal   @map(\"total_amount\") @db.Decimal(14, 3)\n  installmentCount Int       @map(\"installment_count\")\n  frequencyMonths  Int       @map(\"frequency_months\")\n  startDate        DateTime  @map(\"start_date\") @db.Date\n  createdById      String?   @map(\"created_by\") @db.Uuid\n  createdAt        DateTime  @default(now()) @map(\"created_at\")\n  /// Set when an admin cancels the plan early (e.g. owner wants to pay\n  /// differently) — remaining unpaid installments stop counting as active.\n  cancelledAt      DateTime? @map(\"cancelled_at\")\n\n  unit          Unit                       @relation(fields: [unitId], references: [id], onDelete: Cascade)\n  sourceInvoice ServiceChargeInvoice?      @relation(fields: [sourceInvoiceId], references: [id], onDelete: SetNull)\n  createdBy     User?                      @relation(\"ServiceChargePlanCreator\", fields: [createdById], references: [id], onDelete: SetNull)\n  installments  ServiceChargeInstallment[]\n\n  @@index([unitId])\n  @@map(\"service_charge_installment_plans\")\n}\n\n/// One scheduled installment within a plan. Marking it paid creates a real\n/// ServiceChargePayment (same as \"Record payment\" already does) so the\n/// unit's running balance moves through the one ledger, not a parallel one.\nmodel ServiceChargeInstallment {\n  id             String    @id @default(uuid()) @db.Uuid\n  planId         String    @map(\"plan_id\") @db.Uuid\n  /// 1-based position — \"Installment 2 of 4\".\n  sequence       Int\n  amount         Decimal   @db.Decimal(14, 3)\n  dueDate        DateTime  @map(\"due_date\") @db.Date\n  paidAt         DateTime? @map(\"paid_at\") @db.Date\n  paymentId      String?   @unique @map(\"payment_id\") @db.Uuid\n  /// When the \"due in a week\" invoice email last went out for this\n  /// installment — set by the daily cron or the manual \"Send invoice\"\n  /// button, whichever fires first, so it's never sent twice automatically.\n  reminderSentAt DateTime? @map(\"reminder_sent_at\")\n\n  plan    ServiceChargeInstallmentPlan @relation(fields: [planId], references: [id], onDelete: Cascade)\n  payment ServiceChargePayment?        @relation(fields: [paymentId], references: [id], onDelete: SetNull)\n\n  @@unique([planId, sequence])\n  @@map(\"service_charge_installments\")\n}\n\n/// One property's estimated budget for a financial year — a reference\n/// document only (v1 doesn't push its numbers back onto any unit's\n/// service charge amount). Determines what needs to be recovered through\n/// service charges, but that recovery is still set manually per unit.\nmodel AnnualBudget {\n  id          String   @id @default(uuid()) @db.Uuid\n  propertyId  String   @map(\"property_id\") @db.Uuid\n  year        Int\n  createdById String?  @map(\"created_by\") @db.Uuid\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  property     Property            @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  createdBy    User?               @relation(\"AnnualBudgetCreator\", fields: [createdById], references: [id], onDelete: SetNull)\n  incomeLines  BudgetIncomeLine[]\n  expenseLines BudgetExpenseLine[]\n\n  @@unique([propertyId, year])\n  @@map(\"annual_budgets\")\n}\n\n/// One row of budgeted income — Description | No of Units | Amount |\n/// Total Yearly, the exact terminology the spec requires be retained.\nmodel BudgetIncomeLine {\n  id          String  @id @default(uuid()) @db.Uuid\n  budgetId    String  @map(\"budget_id\") @db.Uuid\n  description String\n  units       Int     @map(\"no_of_units\")\n  amount      Decimal @db.Decimal(14, 3)\n  totalYearly Decimal @map(\"total_yearly\") @db.Decimal(14, 3)\n\n  budget AnnualBudget @relation(fields: [budgetId], references: [id], onDelete: Cascade)\n\n  @@map(\"budget_income_lines\")\n}\n\n/// One row of budgeted expenditure — Description | Rate/Month | Rate/Year,\n/// optionally tagged with which Fund it draws from. `description` is free\n/// text (the UI offers the spec's own category list as suggestions, not a\n/// hard enum, so a client can always type something new).\nmodel BudgetExpenseLine {\n  id           String  @id @default(uuid()) @db.Uuid\n  budgetId     String  @map(\"budget_id\") @db.Uuid\n  fundId       String? @map(\"fund_id\") @db.Uuid\n  description  String\n  ratePerMonth Decimal @map(\"rate_per_month\") @db.Decimal(14, 3)\n  ratePerYear  Decimal @map(\"rate_per_year\") @db.Decimal(14, 3)\n\n  budget AnnualBudget @relation(fields: [budgetId], references: [id], onDelete: Cascade)\n  fund   Fund?        @relation(fields: [fundId], references: [id], onDelete: SetNull)\n\n  @@map(\"budget_expense_lines\")\n}\n\n/// Admin-manageable expense categories — same idiom as PropertyType (see\n/// /protected/admin/property-types) instead of a fixed enum, so the list\n/// can grow as the client's own chart of accounts does.\nmodel ExpenseCategoryType {\n  id        String   @id @default(uuid()) @db.Uuid\n  /// Stable slug, e.g. \"administration\" — matches the original hardcoded\n  /// enum values so existing expenses kept their category through the\n  /// migration off that enum.\n  name      String   @unique\n  label     String\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  subcategories ExpenseSubcategoryType[]\n  expenses      Expense[]\n  suppliers     SupplierCategory[]\n\n  @@map(\"expense_category_types\")\n}\n\n/// A real vendor record (company info, contact, contract terms) — suggested\n/// when logging an expense against a category it covers (see\n/// SupplierCategory below and components/expense-category-picker.tsx).\nmodel Supplier {\n  id                        String    @id @default(uuid()) @db.Uuid\n  companyName               String    @map(\"company_name\")\n  companyNameAr             String?   @map(\"company_name_ar\")\n  externalReference         String?   @map(\"external_reference\")\n  /// Whether this supplier can be assigned to new expenses — inactive\n  /// suppliers drop out of the picker but stay on past expenses.\n  active                    Boolean   @default(true)\n  contactPerson             String?   @map(\"contact_person\")\n  phone                     String?\n  whatsapp                  String?\n  email                     String?\n  address                   String?\n  availableForEmergencies   Boolean   @default(false) @map(\"available_for_emergencies\")\n  /// True (the default) means this vendor can be picked for an expense\n  /// against any property. False means only the properties explicitly\n  /// linked via SupplierProperty below are eligible.\n  availableForAllProperties Boolean   @default(true) @map(\"available_for_all_properties\")\n  calloutCharge             Decimal?  @map(\"callout_charge\") @db.Decimal(14, 3)\n  contractStart             DateTime? @map(\"contract_start\") @db.Date\n  contractEnd               DateTime? @map(\"contract_end\") @db.Date\n  contractInfo              String?   @map(\"contract_info\")\n  notes                     String?\n  createdById               String?   @map(\"created_by\") @db.Uuid\n  createdAt                 DateTime  @default(now()) @map(\"created_at\")\n  updatedAt                 DateTime  @updatedAt @map(\"updated_at\")\n\n  createdBy        User?                     @relation(\"SupplierCreator\", fields: [createdById], references: [id], onDelete: SetNull)\n  categories       SupplierCategory[]\n  properties       SupplierProperty[]\n  expenses         Expense[]\n  serviceContracts BuildingServiceContract[]\n  communications   CommunicationLog[]\n\n  @@map(\"suppliers\")\n}\n\n/// The property manager's own agreement with a vendor for a whole\n/// building's shared infrastructure — lift maintenance, fire extinguisher\n/// servicing, generator, pest control, and so on. Distinct from a\n/// Supplier's own contractStart/contractEnd (which just describes that one\n/// vendor's general terms) and from Expense (the recurring bill this\n/// contract eventually generates): this row is the fixed-term agreement\n/// itself, kept so its expiry can be tracked and its signed copy stored.\nmodel BuildingServiceContract {\n  id               String    @id @default(uuid()) @db.Uuid\n  propertyId       String    @map(\"property_id\") @db.Uuid\n  /// Freeform, not an enum — the same \"pick a preset or type your own\"\n  /// idiom as ExpenseCategoryType's subcategories (Elevator, Fire\n  /// Extinguisher, Generator, Pest Control, Water Tank Cleaning, ...).\n  contractType     String    @map(\"contract_type\")\n  supplierId       String?   @map(\"supplier_id\") @db.Uuid\n  startDate        DateTime  @map(\"start_date\") @db.Date\n  /// Null means an open-ended/rolling contract with no fixed expiry.\n  endDate          DateTime? @map(\"end_date\") @db.Date\n  amount           Decimal?  @db.Decimal(14, 3)\n  notes            String?\n  /// The signed contract file, if uploaded. Single file, inline rather\n  /// than routed through EntityDocument — same idiom as Expense's own\n  /// receipt fields.\n  documentFileName String?   @map(\"document_file_name\")\n  documentFilePath String?   @map(\"document_file_path\")\n  documentFileType String?   @map(\"document_file_type\")\n  documentFileSize Int?      @map(\"document_file_size\")\n  createdById      String?   @map(\"created_by\") @db.Uuid\n  createdAt        DateTime  @default(now()) @map(\"created_at\")\n  updatedAt        DateTime  @updatedAt @map(\"updated_at\")\n\n  property  Property  @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  supplier  Supplier? @relation(fields: [supplierId], references: [id], onDelete: SetNull)\n  createdBy User?     @relation(\"BuildingServiceContractCreator\", fields: [createdById], references: [id], onDelete: SetNull)\n\n  @@index([propertyId, endDate])\n  @@map(\"building_service_contracts\")\n}\n\n/// Which expense categories a supplier covers (\"services covered\") — used\n/// to suggest/filter suppliers when logging an expense against a category.\nmodel SupplierCategory {\n  supplierId String @map(\"supplier_id\") @db.Uuid\n  categoryId String @map(\"category_id\") @db.Uuid\n\n  supplier Supplier            @relation(fields: [supplierId], references: [id], onDelete: Cascade)\n  category ExpenseCategoryType @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n\n  @@id([supplierId, categoryId])\n  @@index([categoryId])\n  @@map(\"supplier_categories\")\n}\n\n/// Explicit property links for a supplier that ISN'T available for all\n/// properties (Supplier.availableForAllProperties = false) — only these\n/// properties can use it when logging an expense.\nmodel SupplierProperty {\n  supplierId String @map(\"supplier_id\") @db.Uuid\n  propertyId String @map(\"property_id\") @db.Uuid\n\n  supplier Supplier @relation(fields: [supplierId], references: [id], onDelete: Cascade)\n  property Property @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n\n  @@id([supplierId, propertyId])\n  @@index([propertyId])\n  @@map(\"supplier_properties\")\n}\n\n/// A specific line item within a category (e.g. \"Cleaning Service\" within\n/// \"Services\") — admin-manageable per ExpenseCategoryType above.\nmodel ExpenseSubcategoryType {\n  id         String   @id @default(uuid()) @db.Uuid\n  categoryId String   @map(\"category_id\") @db.Uuid\n  label      String\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n\n  category ExpenseCategoryType @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n\n  @@unique([categoryId, label])\n  @@index([categoryId])\n  @@map(\"expense_subcategory_types\")\n}\n\nmodel MaintenanceRequest {\n  id                String         @id @default(uuid()) @db.Uuid\n  userId            String         @map(\"user_id\") @db.Uuid\n  /// The apartment the issue is in. This is what tells anyone which flat in which\n  /// building to actually go to. Null for a common-area request — one that\n  /// belongs to the property as a whole (lobby, parking, garden) rather than\n  /// a specific tenant's unit. Exactly one of unitId/propertyId is set.\n  unitId            String?        @map(\"unit_id\") @db.Uuid\n  /// Set only for a common-area request (unitId null) — which property the\n  /// shared space belongs to. Redundant with unit.propertyId otherwise, so\n  /// left null when unitId is set rather than duplicating it.\n  propertyId        String?        @map(\"property_id\") @db.Uuid\n  title             String\n  description       String\n  /// Room within the apartment (e.g. \"Kitchen\"), or the common area itself\n  /// (e.g. \"Lobby\", \"Parking\") when unitId is null.\n  location          String\n  priority          Priority       @default(medium)\n  status            RequestStatus  @default(pending)\n  assignedToId      String?        @map(\"assigned_to\") @db.Uuid\n  /// Who actually filed this — set only when an admin creates it on a\n  /// tenant's behalf (via the maintenance dashboard), so the UI can show\n  /// \"Added by <admin>\" distinct from `user` (the tenant it's for). Left\n  /// null for a tenant's own self-reported request; nothing to distinguish\n  /// there since userId already is the reporter in that case.\n  createdById       String?        @map(\"created_by_id\") @db.Uuid\n  notes             String?\n  createdAt         DateTime       @default(now()) @map(\"created_at\")\n  updatedAt         DateTime       @updatedAt @map(\"updated_at\")\n  completedAt       DateTime?      @map(\"completed_at\")\n  enRouteAt         DateTime?      @map(\"en_route_at\")\n  inProgressAt      DateTime?      @map(\"in_progress_at\")\n  /// A held job leaves the worker's active queue and waits for an admin decision.\n  /// The old worker stays assigned as the default choice when work is resumed.\n  holdReason        String?        @map(\"hold_reason\")\n  heldAt            DateTime?      @map(\"held_at\")\n  heldFromStatus    RequestStatus? @map(\"held_from_status\")\n  /// Set when the tenant tells management that their side of the blocker is clear.\n  /// It is only a signal; an admin still chooses the worker and resumes the job.\n  resumeRequestedAt DateTime?      @map(\"resume_requested_at\")\n  /// 4-digit code the tenant gives the worker to confirm completion. Set when the\n  /// worker requests completion, cleared once the code is entered or cancelled.\n  completionCode    String?        @map(\"completion_code\")\n  completionCodeAt  DateTime?      @map(\"completion_code_at\")\n\n  user             User                    @relation(\"RequestOwner\", fields: [userId], references: [id], onDelete: Cascade)\n  unit             Unit?                   @relation(fields: [unitId], references: [id], onDelete: SetNull)\n  property         Property?               @relation(fields: [propertyId], references: [id], onDelete: SetNull)\n  assignedTo       User?                   @relation(\"AssignedWorker\", fields: [assignedToId], references: [id], onDelete: SetNull)\n  createdBy        User?                   @relation(\"RequestCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  attachments      MaintenanceAttachment[]\n  taskLogs         TaskLog[]\n  notifications    Notification[]\n  supplyRequests   SupplyRequest[]\n  whatsappSessions WhatsappSession[]\n\n  @@index([userId])\n  @@index([unitId])\n  @@index([propertyId])\n  @@index([assignedToId])\n  @@index([status])\n  @@map(\"maintenance_requests\")\n}\n\n/// A worker's ask for something needed to finish a held job — a part, a\n/// tool, a purchase. The admin approves (optionally with a note on where it\n/// is / how it was sourced) or denies (with a reason); the worker resumes\n/// the job themselves once they actually have it in hand.\nmodel SupplyRequest {\n  id              String              @id @default(uuid()) @db.Uuid\n  requestId       String              @map(\"request_id\") @db.Uuid\n  /// Short name of what's needed, e.g. \"20m PVC pipe\" or \"replacement water heater\".\n  item            String\n  /// Extra detail from the worker — size, brand, where to buy, cost estimate.\n  notes           String?\n  status          SupplyRequestStatus @default(pending)\n  /// Admin's reason for denying, or a note like \"picked up, ready for you\".\n  adminNote       String?             @map(\"admin_note\")\n  /// The actual price paid, recorded by the admin at the moment of approval.\n  /// Set once and never edited again — decideSupplyRequestAction refuses any\n  /// request that isn't still pending, so this is the permanent cost record\n  /// for the audit trail, unaffected by later job status changes.\n  cost            Decimal?            @db.Decimal(14, 3)\n  /// What the worker says they paid, entered alongside the receipt. A\n  /// suggestion for the admin only — never authoritative and never a\n  /// substitute for `cost`, which the admin sets explicitly on approval.\n  workerCost      Decimal?            @map(\"worker_cost\") @db.Decimal(14, 3)\n  /// Storage object key for a photo/PDF of the purchase receipt the worker\n  /// uploaded as proof of what they already bought. Set once, while the\n  /// request is still pending — see uploadSupplyReceiptAction.\n  receiptPath     String?             @map(\"receipt_path\")\n  receiptFileName String?             @map(\"receipt_file_name\")\n  receiptFileType String?             @map(\"receipt_file_type\")\n  requestedById   String              @map(\"requested_by\") @db.Uuid\n  decidedById     String?             @map(\"decided_by\") @db.Uuid\n  decidedAt       DateTime?           @map(\"decided_at\")\n  createdAt       DateTime            @default(now()) @map(\"created_at\")\n  updatedAt       DateTime            @updatedAt @map(\"updated_at\")\n\n  request     MaintenanceRequest @relation(fields: [requestId], references: [id], onDelete: Cascade)\n  requestedBy User               @relation(\"SupplyRequestedBy\", fields: [requestedById], references: [id], onDelete: Restrict)\n  decidedBy   User?              @relation(\"SupplyDecidedBy\", fields: [decidedById], references: [id], onDelete: SetNull)\n\n  @@index([requestId])\n  @@index([status])\n  @@map(\"supply_requests\")\n}\n\nmodel MaintenanceAttachment {\n  id          String   @id @default(uuid()) @db.Uuid\n  requestId   String   @map(\"request_id\") @db.Uuid\n  fileName    String   @map(\"file_name\")\n  /// Object key inside the MinIO bucket, e.g. \"attachments/<requestId>/<uuid>.jpg\".\n  filePath    String   @map(\"file_path\")\n  fileType    String   @map(\"file_type\")\n  fileSize    Int      @map(\"file_size\")\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  createdById String?  @map(\"created_by\") @db.Uuid\n\n  request   MaintenanceRequest @relation(fields: [requestId], references: [id], onDelete: Cascade)\n  createdBy User?              @relation(fields: [createdById], references: [id], onDelete: SetNull)\n\n  @@index([requestId])\n  @@map(\"maintenance_attachments\")\n}\n\nmodel TaskLog {\n  id          String        @id @default(uuid()) @db.Uuid\n  requestId   String        @map(\"request_id\") @db.Uuid\n  status      RequestStatus\n  changedById String?       @map(\"changed_by\") @db.Uuid\n  notes       String?\n  createdAt   DateTime      @default(now()) @map(\"created_at\")\n\n  request   MaintenanceRequest @relation(fields: [requestId], references: [id], onDelete: Cascade)\n  changedBy User?              @relation(fields: [changedById], references: [id], onDelete: SetNull)\n\n  @@index([requestId])\n  @@map(\"task_logs\")\n}\n\nmodel Notification {\n  id        String   @id @default(uuid()) @db.Uuid\n  userId    String   @map(\"user_id\") @db.Uuid\n  title     String\n  message   String\n  relatedId String?  @map(\"related_to\") @db.Uuid\n  href      String?\n  isRead    Boolean  @default(false) @map(\"is_read\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  user    User                @relation(fields: [userId], references: [id], onDelete: Cascade)\n  related MaintenanceRequest? @relation(fields: [relatedId], references: [id], onDelete: SetNull)\n\n  @@index([userId, isRead])\n  @@map(\"notifications\")\n}\n\n/// What an in-progress WhatsApp conversation with a given phone number is\n/// currently doing — a tenant stepping through \"report an issue\", or a\n/// worker who's been handed a specific task to act on. One row per phone\n/// number; it's overwritten (not appended to) as the conversation moves\n/// forward, since only the current step ever matters.\nenum WhatsappFlow {\n  /// Tenant is being walked through category → location → description →\n  /// confirm to create a new maintenance request.\n  new_request\n  /// Worker has an assigned task in front of them and can reply to move it\n  /// forward (start → in progress → request completion).\n  worker_task\n  /// Worker requested completion; the next message from them is treated as\n  /// the 4-digit code the tenant gave them, not a new command.\n  awaiting_completion_code\n}\n\nmodel WhatsappSession {\n  id        String        @id @default(uuid()) @db.Uuid\n  /// E.164 phone number — the WhatsApp conversation's identity. Looked up\n  /// against User.phone on every inbound message.\n  phone     String        @unique\n  userId    String?       @map(\"user_id\") @db.Uuid\n  flow      WhatsappFlow?\n  /// Free-form step name within the flow (e.g. \"category\", \"location\",\n  /// \"description\", \"confirm\" for new_request). Not used by worker_task /\n  /// awaiting_completion_code, which re-derive state from the live task.\n  step      String?\n  /// Answers collected so far in the current flow (category, location,\n  /// description, ...). Cleared whenever the flow resets or completes.\n  data      Json?\n  /// The task a worker_task / awaiting_completion_code conversation is\n  /// about.\n  taskId    String?       @map(\"task_id\") @db.Uuid\n  updatedAt DateTime      @updatedAt @map(\"updated_at\")\n  createdAt DateTime      @default(now()) @map(\"created_at\")\n\n  user User?               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  task MaintenanceRequest? @relation(fields: [taskId], references: [id], onDelete: SetNull)\n\n  @@index([userId])\n  @@map(\"whatsapp_sessions\")\n}\n\n/// What kind of thing was rejected. Payment and supply-request rejections\n/// already keep their own permanent record on their own model (Payment.status\n/// = rejected, SupplyRequest.status = denied) — this enum only needs to\n/// name them so the admin rejections page can show one merged list.\n/// Property rejection is the odd one out: rejectPropertyAction deletes the\n/// property row outright, so RejectionLog is the ONLY surviving record of it.\nenum RejectionKind {\n  property\n  payment\n  supply_request\n}\n\n/// A permanent audit trail entry for a rejection, written at the moment of\n/// rejection. Required for `property` (whose row is deleted right after), and\n/// written for `payment`/`supply_request` too so the admin rejections page has\n/// one single table to query instead of merging three different models.\nmodel RejectionLog {\n  id           String        @id @default(uuid()) @db.Uuid\n  kind         RejectionKind\n  /// Human-readable label for the rejected thing, e.g. the property name or\n  /// the charge title — captured as text since the underlying row (property)\n  /// may no longer exist.\n  entityLabel  String        @map(\"entity_label\")\n  /// Who the rejection affects, e.g. \"owner@x.com\" or \"tenant@x.com\" —\n  /// captured as text for the same reason as entityLabel.\n  affectedUser String?       @map(\"affected_user\")\n  /// Amount involved, if any (payment rejections only).\n  amount       Decimal?      @db.Decimal(14, 3)\n  reason       String?\n  rejectedById String        @map(\"rejected_by_id\") @db.Uuid\n  rejectedBy   User          @relation(fields: [rejectedById], references: [id], onDelete: Restrict)\n  createdAt    DateTime      @default(now()) @map(\"created_at\")\n\n  @@index([kind])\n  @@index([createdAt])\n  @@map(\"rejection_logs\")\n}\n\n/// A Rawazen Services invoice for an Independent or Building Management\n/// unit — maintenance/expenses billed to the landlord, rent Rawazen\n/// collected credited as negative lines. Matches the client's Brisk\n/// \"Invoice 75\" layout (see lib/pdf/services-invoice.tsx).\nmodel ServicesInvoice {\n  id            String   @id @default(uuid()) @db.Uuid\n  invoiceNumber Int      @unique @map(\"invoice_number\")\n  propertyId    String   @map(\"property_id\") @db.Uuid\n  unitId        String   @map(\"unit_id\") @db.Uuid\n  tenancyId     String?  @map(\"tenancy_id\") @db.Uuid\n  issueDate     DateTime @map(\"issue_date\") @db.Date\n  periodStart   DateTime @map(\"period_start\") @db.Date\n  periodEnd     DateTime @map(\"period_end\") @db.Date\n  billedName    String   @map(\"billed_name\")\n  billedAddress String   @map(\"billed_address\")\n  /// \"issued\" until an admin marks it paid, or auto-paid when the total\n  /// is a credit (rent collected exceeds costs).\n  status        String   @default(\"issued\")\n  total         Decimal  @db.Decimal(14, 3)\n  createdById   String?  @map(\"created_by\") @db.Uuid\n  createdAt     DateTime @default(now()) @map(\"created_at\")\n\n  property  Property              @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  unit      Unit                  @relation(fields: [unitId], references: [id], onDelete: Cascade)\n  tenancy   Tenancy?              @relation(fields: [tenancyId], references: [id], onDelete: SetNull)\n  createdBy User?                 @relation(\"ServicesInvoiceCreator\", fields: [createdById], references: [id], onDelete: SetNull)\n  lines     ServicesInvoiceLine[]\n\n  @@index([propertyId, issueDate])\n  @@index([unitId, issueDate])\n  @@map(\"services_invoices\")\n}\n\nmodel ServicesInvoiceLine {\n  id          String  @id @default(uuid()) @db.Uuid\n  invoiceId   String  @map(\"invoice_id\") @db.Uuid\n  sequence    Int\n  qty         Decimal @default(1) @db.Decimal(10, 2)\n  item        String\n  description String\n  unitPrice   Decimal @map(\"unit_price\") @db.Decimal(14, 3)\n\n  invoice ServicesInvoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n\n  @@index([invoiceId])\n  @@map(\"services_invoice_lines\")\n}\n\n/// A conversation Rawazen had with someone — phone, visit, WhatsApp, SMS\n/// or email — logged by staff so the history is complete even when it\n/// didn't go through the in-app channels.\nmodel CommunicationLog {\n  id          String   @id @default(uuid()) @db.Uuid\n  channel     String\n  direction   String\n  aboutKind   String   @map(\"about_kind\")\n  partyUserId String?  @map(\"party_user_id\") @db.Uuid\n  supplierId  String?  @map(\"supplier_id\") @db.Uuid\n  partyName   String   @map(\"party_name\")\n  partyPhone  String?  @map(\"party_phone\")\n  subject     String\n  body        String\n  occurredAt  DateTime @map(\"occurred_at\")\n  createdById String   @map(\"created_by\") @db.Uuid\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n\n  partyUser User?     @relation(\"CommunicationParty\", fields: [partyUserId], references: [id], onDelete: SetNull)\n  supplier  Supplier? @relation(fields: [supplierId], references: [id], onDelete: SetNull)\n  createdBy User      @relation(\"CommunicationLogger\", fields: [createdById], references: [id], onDelete: Restrict)\n\n  @@index([occurredAt])\n  @@index([channel])\n  @@index([createdById])\n  @@map(\"communication_logs\")\n}\n"
}

